mapper.select:
SELECT user_id, username, real_name, email, phone, status, avatar, last_login_time, create_time FROM sys_user WHERE is_deleted = 0
AND username LIKE CONCAT('%', #{username}, '%')
AND real_name LIKE CONCAT('%', #{realName}, '%')
AND status = #{status}
ORDER BY user_id DESC LIMIT #{offset}, #{pageSize}

mapper.update:
UPDATE sys_user
SET real_name = #{realName}, email = #{email}, phone = #{phone}, status = #{status}, avatar = #{avatar}
WHERE user_id = #{userId} AND is_deleted = 0
